"""Review-bundle verification result helpers for eval target finalization."""

from __future__ import annotations

import re
from collections import deque

import src.key_catalog
from src.key_catalog import PK_CONTROL_ID, PK_INTENT_ID, PK_REASON
from src.types.typed import (
    JsonObject,
    as_json_array,
    as_json_object,
    as_json_object_list,
    as_str,
)

from ...scoring import is_accepted_eval_skip
from ...types import ActionExecutionResult
from .state import PageLoopState

_US_ZIP_PATTERN = re.compile(r"\d{5}(?:-\d{4})?")
_UK_POSTCODE_EXAMPLE_PATTERN = re.compile(
    r"\b[A-Z]{1,2}\d[A-Z\d]?\s*\d[A-Z]{2}\b",
    re.IGNORECASE,
)
_UK_POSTCODE_MARKER_PATTERN = re.compile(
    r"\b(?:gb|great britain|uk|united kingdom)\b",
    re.IGNORECASE,
)


def _final_validity_accepts_verify_failures(after_validity: JsonObject) -> bool:
    return bool(after_validity.get("actionable_form_valid", False)) and bool(
        after_validity.get("non_system_form_valid", False),
    )


def _verification_result_passed(
    result: ActionExecutionResult,
    after_validity: JsonObject,
) -> bool:
    if result.passed or is_accepted_eval_skip(result):
        return True
    return (
        _final_validity_accepts_verify_failures(after_validity)
        and result.fill_ok
        and not result.verify_ok
        and result.reason == "verify_failed"
    )


def _is_us_zip_for_uk_postcode(
    result: ActionExecutionResult,
    state: PageLoopState,
) -> bool:
    field = next(
        (item for item in state.all_fields if item.control_id == result.control_id),
        None,
    )
    if field is None:
        return False
    label = field.question_text.casefold()
    uk_marked = "postcode" in label and bool(
        _UK_POSTCODE_MARKER_PATTERN.search(label)
        or _UK_POSTCODE_EXAMPLE_PATTERN.search(label)
    )
    value = result.expected_value
    return bool(
        uk_marked
        and isinstance(value, str)
        and _US_ZIP_PATTERN.fullmatch(value.strip())
    )


def _verification_result_payload(
    result: ActionExecutionResult,
    state: PageLoopState,
    after_validity: JsonObject,
) -> JsonObject:
    locale_incompatible = _is_us_zip_for_uk_postcode(result, state)
    reason = "locale_incompatible_value" if locale_incompatible else result.reason
    return as_json_object(
        {
            PK_CONTROL_ID: result.control_id,
            src.key_catalog.SV_PASSED: not locale_incompatible
            and _verification_result_passed(result, after_validity),
            PK_INTENT_ID: result.intent_id,
            "expected": result.expected_value,
            "observed": result.observed_value,
            PK_REASON: reason,
            "tool_error": not result.fill_ok,
        }
    )


def verification_results_from_state(
    state: PageLoopState,
    after_validity: JsonObject,
) -> list[JsonObject]:
    return [
        _verification_result_payload(result, state, after_validity)
        for result in state.all_execution_results
    ]


def _field_tool_calls(
    result: ActionExecutionResult,
    action: JsonObject,
    operation: str,
) -> list[JsonObject]:
    if result.skipped:
        return []
    return [
        as_json_object(
            {
                "tool_name": operation,
                src.key_catalog.ARG_ARGS: {
                    "value": action.get("value", result.expected_value)
                },
                "result_summary": result.reason,
                src.key_catalog.PK_SUCCESS: result.fill_ok,
                "error_message": None if result.fill_ok else result.reason,
                src.key_catalog.PK_DURATION_MS: result.elapsed_ms,
            }
        )
    ]


def _optional_text(value: object) -> str | None:
    if value is None:
        return None
    return str(value)


def _field_trace_payload(
    result: ActionExecutionResult,
    action: JsonObject,
    state: PageLoopState,
    after_validity: JsonObject,
) -> JsonObject:
    operation = (
        as_str(action.get(src.key_catalog.PK_OPERATION), "")
        or result.widget_kind
        or "fill"
    )
    locale_incompatible = _is_us_zip_for_uk_postcode(result, state)
    verification_passed = (
        _verification_result_passed(result, after_validity) and not locale_incompatible
    )
    trace_reason = "locale_incompatible_value" if locale_incompatible else result.reason
    expected_state = _optional_text(result.expected_value)
    observed_after = _optional_text(result.observed_value)
    return as_json_object(
        {
            PK_CONTROL_ID: result.control_id,
            PK_INTENT_ID: result.intent_id,
            "fill_ok": result.fill_ok,
            "value_used": action.get("value", result.expected_value),
            "widget_kind": result.widget_kind or None,
            src.key_catalog.PK_QUESTION_TEXT: result.label or None,
            "decision_source": result.source,
            "intent_matched": bool(result.intent_id),
            "tool_calls": _field_tool_calls(result, action, operation),
            src.key_catalog.PK_OPERATION: operation,
            "execution_attempted": not result.skipped,
            src.key_catalog.PK_VERIFICATION_PASSED: None
            if result.skipped
            else verification_passed,
            "observed_after": observed_after,
            "expected_state": expected_state,
            "mismatch_reason": None
            if result.skipped or verification_passed
            else trace_reason,
            "verification_result": trace_reason,
            "skipped_due_to_condition": result.skipped,
            "retry_count": 0,
            src.key_catalog.PK_ERROR: None
            if result.skipped or result.fill_ok
            else result.reason,
        }
    )


def field_trace_payloads_from_state(
    state: PageLoopState,
    after_validity: JsonObject | None = None,
) -> list[JsonObject]:
    actions_by_control_id: dict[str, deque[JsonObject]] = {}
    for action in as_json_object_list(state.all_actions):
        actions_by_control_id.setdefault(
            as_str(action.get(PK_CONTROL_ID), ""), deque()
        ).append(action)
    validity = after_validity or {}
    traces: list[JsonObject] = []
    retry_counts: dict[str, int] = {}
    for result in state.all_execution_results:
        actions = actions_by_control_id.get(result.control_id)
        action = actions.popleft() if actions else {}
        retry_count = retry_counts.get(result.control_id, 0)
        retry_counts[result.control_id] = retry_count + 1
        payload = _field_trace_payload(result, action, state, validity)
        payload["retry_count"] = retry_count
        traces.append(payload)
    return traces


def summary_with_field_traces(
    summary: object,
    state: PageLoopState,
) -> JsonObject:
    result = as_json_object(summary)
    result[src.key_catalog.SK_FIELD_TRACES] = as_json_array(
        field_trace_payloads_from_state(state, state.after_validity)
    )
    return result


__all__ = [
    "field_trace_payloads_from_state",
    "summary_with_field_traces",
    "verification_results_from_state",
]

